UPDATE svc_mbr_session
SET session_end_dt = CURRENT_TIMESTAMP,
    actv_yn = 'N',
    end_type_cd = #{endType}
WHERE session_id = #{sessionId}
AND actv_yn = 'Y'

UPDATE svc_mbr_session s LEFT JOIN persistent_logins p ON s.session_id = p.session_id SET s.session_end_dt = CURRENT_TIMESTAMP, s.actv_yn = 'N', s.end_type_cd = #{endType} WHERE s.session_sn = #{sn} AND s.actv_yn = 'Y' AND ( p.session_id IS NULL /* remember-me 토큰이 없는 경우 */
OR p.last_used < DATE_SUB(NOW(), INTERVAL #{tokenValiditySeconds} SECOND) /* 토큰이 만료된 경우 */
)

UPDATE svc_mbr_session s LEFT JOIN persistent_logins p ON s.session_id = p.session_id SET s.session_end_dt = CURRENT_TIMESTAMP, s.actv_yn = 'N', s.end_type_cd = #{endType} WHERE s.session_sn = #{sn} AND s.actv_yn = 'Y' AND ( p.session_id IS NULL /* remember-me 토큰이 없는 경우 */
OR p.last_used < DATE_SUB(NOW(), INTERVAL #{tokenValiditySeconds} SECOND) /* 토큰이 만료된 경우 */
)

